{"uncertainty": 0.3, "outcome": "RTL (apb_gpio.v) and a self-checking testbench (apb_gpio_tb.v) for the APB4 GPIO block with interrupts, submitted for the platform's lint, simulation and synthesis checks. No formal_spec file is included.", "artifacts": [{"kind": "rtl_source", "title": "apb_gpio RTL", "summary": "Zero-wait-state APB4 GPIO block for [requirement:req-837b82982d]. Registers are 32 bits wide and masked by PINS, writes merge by byte strobe, the decode rejects unaligned addresses, addresses above bit 5 and indices above 8, and PSLVERR follows the policy in [artifact:prj-b46fec8693.interface-spec.a1]. Detection, status and irq follow [artifact:prj-b46fec8693.microarchitecture.a1] section 3, with a detection winning over a clear in the same cycle."}, {"kind": "testbench", "title": "apb_gpio self-checking testbench", "summary": "Runs N=8 and N=32 instances on one APB bus. Each instance is checked against an independently written reference model on every clock, and against hand-computed expected values from [artifact:prj-b46fec8693.interface-spec.a1] sections 3 to 8. Covers reset values, partial strobes, bits above N, DATA_IN read-only, unmapped and aliasing addresses, all four detection kinds, an edge that fires once, a level that sets again after a clear, detection beating a clear, a one-cycle pulse, partial W1C, the irq mask, back-to-back transfers and a second reset."}], "files": [{"path": "apb_gpio.v", "kind": "rtl_source", "title": "apb_gpio RTL", "summary": "Implements [artifact:prj-b46fec8693.microarchitecture.a1]: pready tied high, access = psel && penable, 32-bit registers masked by PINS, combinational next-state and read multiplexer with defaults (no latches), and a synchronous active-low reset of every register and both input samples. Serves [requirement:req-837b82982d].", "entry": "apb_gpio"}, {"path": "apb_gpio_tb.v", "kind": "testbench", "title": "apb_gpio testbench", "summary": "Self-checking testbench for [artifact:prj-b46fec8693.interface-spec.a1] section 8 coverage at N=8 and N=32. Failures are reported with $error; one NIRMAAN-SIM verdict line is printed before $finish.", "entry": "apb_gpio_tb"}], "tool_runs": [], "claims": ["The hand-computed expected values in the testbench were derived from the timing rules in interface_spec.md section 4. Neither they nor the RTL have been simulated, linted or synthesized by this seat.", "Width and multi-driver hazards in the testbench were avoided by hand (sized literals, separate monitor counters). Whether Verilator accepts the testbench without warnings is not known until the platform runs it."], "escalation": null, "notes": "No formal_spec (.sby) is submitted, so the formal.run and formal.cover requirements do not apply to this result. The microarchitecture plans apb_gpio.sby and apb_gpio_n32.sby; that proof is still owed in a follow-up. The testbench uses # delays and so needs a timing-capable simulator (Icarus, or Verilator with --timing or --binary). There is no `timescale in either file, which avoids Verilator's TIMESCALEMOD error. Testbench reads use pstrb=0 but pass arbitrary pwdata. The reference model decodes by full-address equality and derives its pin mask as ~(all-ones << N), separately from the RTL's form; detection and merge are written as similar vector equations. Before relying on the test, it should be checked against a deliberately broken design (for example, clear applied after detection)."}
=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO block with interrupts.
// Implements interface_spec.md and microarchitecture.md (rtl/apb-gpio).
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output reg  [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // Bits 0 to N-1 set.
    localparam [31:0] PINS = {32{1'b1}} >> (32 - N);

    // State
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] in_q;
    reg [31:0] in_prev_q;
    reg [31:0] rise_en_q;
    reg [31:0] fall_en_q;
    reg [31:0] high_en_q;
    reg [31:0] low_en_q;
    reg [31:0] intr_en_q;
    reg [31:0] status_q;

    // Next state
    reg [31:0] data_out_d;
    reg [31:0] dir_d;
    reg [31:0] rise_en_d;
    reg [31:0] fall_en_d;
    reg [31:0] high_en_d;
    reg [31:0] low_en_d;
    reg [31:0] intr_en_d;
    reg [31:0] status_d;
    reg [31:0] clear;

    // Widened inputs
    reg [31:0] addr_ext;
    reg [31:0] in_ext;
    reg [31:0] rdata_sel;

    always @* begin
        addr_ext = 32'd0;
        addr_ext[ADDR_WIDTH-1:0] = paddr;
    end

    always @* begin
        in_ext = 32'd0;
        in_ext[N-1:0] = gpio_in;
    end

    // Decode
    wire [3:0]  index  = addr_ext[5:2];
    wire        mapped = (addr_ext[1:0] == 2'b00) && (addr_ext[31:6] == 26'd0) &&
                         (index <= IDX_INTR_STATUS);
    wire        access = psel && penable;
    wire        wr_en  = access && pwrite && mapped;
    wire        rd_en  = access && !pwrite && mapped;

    wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wmask     = strb_mask & PINS;
    wire [31:0] wbits     = pwdata & wmask;

    // Detection
    wire [31:0] rise     = in_q & ~in_prev_q;
    wire [31:0] fall     = ~in_q & in_prev_q;
    wire [31:0] detected = ((rise & rise_en_q) | (fall & fall_en_q) |
                            (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;

    // Next-state logic
    always @* begin
        data_out_d = data_out_q;
        dir_d      = dir_q;
        rise_en_d  = rise_en_q;
        fall_en_d  = fall_en_q;
        high_en_d  = high_en_q;
        low_en_d   = low_en_q;
        intr_en_d  = intr_en_q;
        clear      = 32'd0;
        if (wr_en) begin
            case (index)
                IDX_DATA_OUT:    data_out_d = (data_out_q & ~wmask) | wbits;
                IDX_DIR:         dir_d      = (dir_q      & ~wmask) | wbits;
                IDX_INTR_RISE:   rise_en_d  = (rise_en_q  & ~wmask) | wbits;
                IDX_INTR_FALL:   fall_en_d  = (fall_en_q  & ~wmask) | wbits;
                IDX_INTR_HIGH:   high_en_d  = (high_en_q  & ~wmask) | wbits;
                IDX_INTR_LOW:    low_en_d   = (low_en_q   & ~wmask) | wbits;
                IDX_INTR_ENABLE: intr_en_d  = (intr_en_q  & ~wmask) | wbits;
                IDX_INTR_STATUS: clear      = wbits;
                default:         clear      = 32'd0;
            endcase
        end
        // Detection is ORed last: it beats a clear on the same edge.
        status_d = (status_q & ~clear) | detected;
    end

    // Registers: synchronous, active-low reset
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
            rise_en_q  <= 32'd0;
            fall_en_q  <= 32'd0;
            high_en_q  <= 32'd0;
            low_en_q   <= 32'd0;
            intr_en_q  <= 32'd0;
            status_q   <= 32'd0;
        end else begin
            data_out_q <= data_out_d;
            dir_q      <= dir_d;
            in_q       <= in_ext;
            in_prev_q  <= in_q;
            rise_en_q  <= rise_en_d;
            fall_en_q  <= fall_en_d;
            high_en_q  <= high_en_d;
            low_en_q   <= low_en_d;
            intr_en_q  <= intr_en_d;
            status_q   <= status_d;
        end
    end

    // Read data
    always @* begin
        case (index)
            IDX_DATA_OUT:    rdata_sel = data_out_q;
            IDX_DIR:         rdata_sel = dir_q;
            IDX_DATA_IN:     rdata_sel = in_q;
            IDX_INTR_RISE:   rdata_sel = rise_en_q;
            IDX_INTR_FALL:   rdata_sel = fall_en_q;
            IDX_INTR_HIGH:   rdata_sel = high_en_q;
            IDX_INTR_LOW:    rdata_sel = low_en_q;
            IDX_INTR_ENABLE: rdata_sel = intr_en_q;
            IDX_INTR_STATUS: rdata_sel = status_q;
            default:         rdata_sel = 32'd0;
        endcase
        prdata = rd_en ? rdata_sel : 32'd0;
    end

    assign pready   = 1'b1;
    assign pslverr  = access && (!mapped || (pwrite && (index == IDX_DATA_IN)));
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & intr_en_q);

endmodule
=== END FILE ===
