// Reference model of interface_spec.md, written separately from the RTL.
module apb_gpio_ref #(parameter integer N = 8) (
    input  wire        pclk,
    input  wire        presetn,
    input  wire [7:0]  paddr,
    input  wire        psel,
    input  wire        penable,
    input  wire        pwrite,
    input  wire [31:0] pwdata,
    input  wire [3:0]  pstrb,
    input  wire [31:0] pins,
    output wire [31:0] m_prdata,
    output wire        m_pslverr,
    output wire [31:0] m_out,
    output wire [31:0] m_oe,
    output wire        m_irq
);
    wire [31:0] valid = ~(32'hFFFF_FFFF << N);
    reg  [31:0] r_out, r_oe, r_in, r_prev, r_rise, r_fall, r_high, r_low, r_en, r_stat;
    wire acc = psel & penable;
    wire dow = acc & pwrite;
    wire [31:0] lanes = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & valid;
    wire h_out  = (paddr == 8'h00);
    wire h_oe   = (paddr == 8'h04);
    wire h_in   = (paddr == 8'h08);
    wire h_rise = (paddr == 8'h0C);
    wire h_fall = (paddr == 8'h10);
    wire h_high = (paddr == 8'h14);
    wire h_low  = (paddr == 8'h18);
    wire h_en   = (paddr == 8'h1C);
    wire h_stat = (paddr == 8'h20);
    wire known  = h_out | h_oe | h_in | h_rise | h_fall | h_high | h_low | h_en | h_stat;
    wire [31:0] det = ((r_in & ~r_prev & r_rise) | (~r_in & r_prev & r_fall) |
                       (r_in & r_high) | (~r_in & r_low)) & valid;
    wire [31:0] clr = (dow & h_stat) ? (pwdata & lanes) : 32'd0;
    wire [31:0] sel = h_out  ? r_out  :
                      h_oe   ? r_oe   :
                      h_in   ? r_in   :
                      h_rise ? r_rise :
                      h_fall ? r_fall :
                      h_high ? r_high :
                      h_low  ? r_low  :
                      h_en   ? r_en   :
                      h_stat ? r_stat : 32'd0;
    assign m_prdata  = (acc & ~pwrite & known) ? sel : 32'd0;
    assign m_pslverr = acc & (~known | (pwrite & h_in));
    assign m_out     = r_out;
    assign m_oe      = r_oe;
    assign m_irq     = |(r_stat & r_en);

    always @(posedge pclk) begin
        if (!presetn) begin
            r_out <= 32'd0; r_oe <= 32'd0; r_in <= 32'd0; r_prev <= 32'd0;
            r_rise <= 32'd0; r_fall <= 32'd0; r_high <= 32'd0; r_low <= 32'd0;
            r_en <= 32'd0; r_stat <= 32'd0;
        end else begin
            if (dow & h_out)  r_out  <= (r_out  & ~lanes) | (pwdata & lanes);
            if (dow & h_oe)   r_oe   <= (r_oe   & ~lanes) | (pwdata & lanes);
            if (dow & h_rise) r_rise <= (r_rise & ~lanes) | (pwdata & lanes);
            if (dow & h_fall) r_fall <= (r_fall & ~lanes) | (pwdata & lanes);
            if (dow & h_high) r_high <= (r_high & ~lanes) | (pwdata & lanes);
            if (dow & h_low)  r_low  <= (r_low  & ~lanes) | (pwdata & lanes);
            if (dow & h_en)   r_en   <= (r_en   & ~lanes) | (pwdata & lanes);
            r_in   <= pins & valid;
            r_prev <= r_in;
            r_stat <= (r_stat & ~clr) | det;
        end
    end
endmodule

module apb_gpio_tb;
    reg         pclk = 1'b0;
    reg         presetn;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [7:0]  paddr;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] pins;

    wire [31:0] prdata8, prdata32;
    wire        pready8, pready32, pslverr8, pslverr32;
    wire [7:0]  out8, oe8;
    wire [31:0] out32, oe32;
    wire        irq8, irq32;

    wire [31:0] m8_rd, m32_rd, m8_out, m8_oe, m32_out, m32_oe;
    wire        m8_err, m32_err, m8_irq, m32_irq;

    integer passed;
    integer failed;
    integer mon_pass = 0;
    integer mon_fail = 0;
    integer pa_ok;
    reg     checking;
    reg [8*64-1:0] nonce;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8),
        .pready(pready8), .pslverr(pslverr8), .gpio_in(pins[7:0]),
        .gpio_out(out8), .gpio_oe(oe8), .irq(irq8));

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32),
        .pready(pready32), .pslverr(pslverr32), .gpio_in(pins),
        .gpio_out(out32), .gpio_oe(oe32), .irq(irq32));

    apb_gpio_ref #(.N(8)) ref8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .pins(pins),
        .m_prdata(m8_rd), .m_pslverr(m8_err), .m_out(m8_out), .m_oe(m8_oe), .m_irq(m8_irq));

    apb_gpio_ref #(.N(32)) ref32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .pins(pins),
        .m_prdata(m32_rd), .m_pslverr(m32_err), .m_out(m32_out), .m_oe(m32_oe), .m_irq(m32_irq));

    always #5 pclk = ~pclk;

    // Cycle-by-cycle comparison with the reference model, just before each edge.
    always @(posedge pclk) begin
        if (checking) begin
            if ((prdata8 === m8_rd) && (pslverr8 === m8_err) && (pready8 === 1'b1) &&
                ({24'd0, out8} === m8_out) && ({24'd0, oe8} === m8_oe) && (irq8 === m8_irq))
                mon_pass = mon_pass + 1;
            else begin
                mon_fail = mon_fail + 1;
                $error("N8 model mismatch t=%0t prdata %h/%h err %b/%b out %h/%h oe %h/%h irq %b/%b",
                       $time, prdata8, m8_rd, pslverr8, m8_err, out8, m8_out, oe8, m8_oe, irq8, m8_irq);
            end
            if ((prdata32 === m32_rd) && (pslverr32 === m32_err) && (pready32 === 1'b1) &&
                (out32 === m32_out) && (oe32 === m32_oe) && (irq32 === m32_irq))
                mon_pass = mon_pass + 1;
            else begin
                mon_fail = mon_fail + 1;
                $error("N32 model mismatch t=%0t prdata %h/%h err %b/%b out %h/%h oe %h/%h irq %b/%b",
                       $time, prdata32, m32_rd, pslverr32, m32_err, out32, m32_out, oe32, m32_oe, irq32, m32_irq);
            end
        end
    end

    task chk(input ok, input integer tag);
        begin
            if (ok) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check %0d failed at t=%0t", tag, $time);
            end
        end
    endtask

    task chk32(input [31:0] got, input [31:0] exp, input [7:0] a, input integer tag);
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check %0d addr %h at t=%0t: got %h expected %h", tag, a, $time, got, exp);
            end
        end
    endtask

    // Setup then access; leaves the bus in the access phase (for back-to-back).
    task xfer(input w, input [7:0] a, input [31:0] d, input [3:0] s,
              input use_exp, input [31:0] exp32, input exp_err);
        reg [31:0] e;
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = w; paddr = a; pwdata = d;
            pstrb = w ? s : 4'b0000;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            e = (w || exp_err) ? 32'd0 : exp32;
            chk((pready32 === 1'b1) && (pready8 === 1'b1), 1);
            chk((pslverr32 === exp_err) && (pslverr8 === exp_err), 2);
            chk32(prdata32, m32_rd, a, 3);
            chk32(prdata8, m8_rd, a, 4);
            if (use_exp) begin
                chk32(prdata32, e, a, 5);
                chk32(prdata8, e & 32'h0000_00FF, a, 6);
            end
        end
    endtask

    task idle;
        begin
            @(negedge pclk);
            psel = 1'b0; penable = 1'b0; pwrite = 1'b0; paddr = 8'h00;
            pwdata = 32'd0; pstrb = 4'b0000;
        end
    endtask

    task wr(input [7:0] a, input [31:0] d, input [3:0] s, input exp_err);
        begin
            xfer(1'b1, a, d, s, 1'b0, 32'd0, exp_err);
            idle;
        end
    endtask

    task rd(input [7:0] a, input [31:0] exp32, input exp_err);
        begin
            xfer(1'b0, a, 32'hC0DE_0000, 4'b0000, 1'b1, exp32, exp_err);
            idle;
        end
    endtask

    // Write whose setup cycle also changes the pins.
    task wr_pins(input [7:0] a, input [31:0] d, input [3:0] s, input [31:0] p);
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = a; pwdata = d; pstrb = s;
            pins = p;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk((pslverr32 === 1'b0) && (pslverr8 === 1'b0), 7);
            idle;
        end
    endtask

    task set_pins(input [31:0] p);
        begin
            @(negedge pclk);
            pins = p;
        end
    endtask

    task waitn(input integer n);
        begin
            repeat (n) @(negedge pclk);
        end
    endtask

    task chk_irq(input e32, input e8);
        begin
            #1;
            chk((irq32 === e32) && (irq8 === e8), 8);
        end
    endtask

    task chk_pins(input [31:0] e_out, input [31:0] e_oe);
        begin
            #1;
            chk32(out32, e_out, 8'hEE, 9);
            chk32({24'd0, out8}, e_out & 32'h0000_00FF, 8'hEE, 10);
            chk32(oe32, e_oe, 8'hEE, 11);
            chk32({24'd0, oe8}, e_oe & 32'h0000_00FF, 8'hEE, 12);
        end
    endtask

    task do_reset;
        begin
            @(negedge pclk);
            presetn = 1'b0; psel = 1'b0; penable = 1'b0;
            repeat (3) @(negedge pclk);
            presetn = 1'b1;
        end
    endtask

    // Read/write register test with partial strobes.
    task rwt(input [7:0] a);
        begin
            wr(a, 32'hFFFF_FFFF, 4'b1111, 1'b0);
            rd(a, 32'hFFFF_FFFF, 1'b0);
            wr(a, 32'h0000_0000, 4'b0110, 1'b0);
            rd(a, 32'hFF00_00FF, 1'b0);
            wr(a, 32'h00AB_0000, 4'b0100, 1'b0);
            rd(a, 32'hFFAB_00FF, 1'b0);
            wr(a, 32'h0000_0000, 4'b1111, 1'b0);
            rd(a, 32'h0000_0000, 1'b0);
        end
    endtask

    task bad(input [7:0] a);
        begin
            wr(a, 32'hFFFF_FFFF, 4'b1111, 1'b1);
            rd(a, 32'h0000_0000, 1'b1);
        end
    endtask

    initial begin
        passed = 0; failed = 0; checking = 1'b0; nonce = 0;
        presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
        paddr = 8'h00; pwdata = 32'd0; pstrb = 4'b0000; pins = 32'd0;
        pa_ok = $value$plusargs("nirmaan_nonce=%s", nonce);

        // Reset values
        do_reset;
        checking = 1'b1;
        chk_pins(32'd0, 32'd0);
        chk_irq(1'b0, 1'b0);
        rd(8'h00, 32'd0, 1'b0);
        rd(8'h04, 32'd0, 1'b0);
        rd(8'h08, 32'd0, 1'b0);
        rd(8'h0C, 32'd0, 1'b0);
        rd(8'h10, 32'd0, 1'b0);
        rd(8'h14, 32'd0, 1'b0);
        rd(8'h18, 32'd0, 1'b0);
        rd(8'h1C, 32'd0, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        // DATA_OUT
        wr(8'h00, 32'hA5A5_A5A5, 4'b1111, 1'b0);
        rd(8'h00, 32'hA5A5_A5A5, 1'b0);
        chk_pins(32'hA5A5_A5A5, 32'd0);
        wr(8'h00, 32'h1234_5678, 4'b0101, 1'b0);
        rd(8'h00, 32'hA534_A578, 1'b0);
        wr(8'h00, 32'hFFFF_FFFF, 4'b0000, 1'b0);
        rd(8'h00, 32'hA534_A578, 1'b0);
        wr(8'h00, 32'hFFFF_FF00, 4'b1111, 1'b0);
        rd(8'h00, 32'hFFFF_FF00, 1'b0);
        chk_pins(32'hFFFF_FF00, 32'd0);

        // DIR
        wr(8'h04, 32'h0F0F_F0F0, 4'b1111, 1'b0);
        wr(8'h04, 32'hFF00_0000, 4'b1000, 1'b0);
        rd(8'h04, 32'hFF0F_F0F0, 1'b0);
        chk_pins(32'hFFFF_FF00, 32'hFF0F_F0F0);
        wr(8'h04, 32'h0000_00C3, 4'b0001, 1'b0);
        rd(8'h04, 32'hFF0F_F0C3, 1'b0);
        chk_pins(32'hFFFF_FF00, 32'hFF0F_F0C3);

        // Detection enables and INTR_ENABLE
        rwt(8'h0C);
        rwt(8'h10);
        rwt(8'h14);
        rwt(8'h1C);
        rd(8'h20, 32'd0, 1'b0);

        // INTR_LOW with pins low sets status
        rwt(8'h18);
        rd(8'h20, 32'hFFFF_FFFF, 1'b0);
        chk_irq(1'b0, 1'b0);
        wr(8'h1C, 32'h0000_0100, 4'b1111, 1'b0);
        chk_irq(1'b1, 1'b0);
        wr(8'h20, 32'hFFFF_FFFF, 4'b0001, 1'b0);
        rd(8'h20, 32'hFFFF_FF00, 1'b0);
        chk_irq(1'b1, 1'b0);
        wr(8'h20, 32'h0000_0F00, 4'b1111, 1'b0);
        rd(8'h20, 32'hFFFF_F000, 1'b0);
        chk_irq(1'b0, 1'b0);
        wr(8'h20, 32'h00FF_0000, 4'b1011, 1'b0);
        rd(8'h20, 32'hFFFF_F000, 1'b0);
        wr(8'h20, 32'hFFFF_FFFF, 4'b1111, 1'b0);
        rd(8'h20, 32'd0, 1'b0);
        wr(8'h1C, 32'd0, 4'b1111, 1'b0);

        // DATA_IN
        set_pins(32'hDEAD_BEEF);
        waitn(2);
        rd(8'h08, 32'hDEAD_BEEF, 1'b0);
        wr(8'h08, 32'h0000_0000, 4'b1111, 1'b1);
        rd(8'h08, 32'hDEAD_BEEF, 1'b0);
        set_pins(32'h0000_0000);
        waitn(3);
        rd(8'h08, 32'd0, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        // PSLVERR and unmapped addresses
        bad(8'h24); bad(8'h28); bad(8'h3C); bad(8'h40); bad(8'h44);
        bad(8'h60); bad(8'h80); bad(8'hA0); bad(8'hFC);
        bad(8'h01); bad(8'h02); bad(8'h03); bad(8'h05); bad(8'h21); bad(8'h23);
        rd(8'h00, 32'hFFFF_FF00, 1'b0);
        rd(8'h04, 32'hFF0F_F0C3, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        // D1: rising edge fires once
        wr(8'h0C, 32'h8000_0003, 4'b1111, 1'b0);
        set_pins(32'h8000_0001);
        waitn(3);
        rd(8'h20, 32'h8000_0001, 1'b0);
        wr(8'h20, 32'h8000_0001, 4'b1111, 1'b0);
        waitn(2);
        rd(8'h20, 32'd0, 1'b0);

        // D2: falling edge
        wr(8'h10, 32'h0000_0004, 4'b1111, 1'b0);
        set_pins(32'h8000_0005);
        waitn(3);
        rd(8'h20, 32'd0, 1'b0);
        set_pins(32'h8000_0001);
        waitn(3);
        rd(8'h20, 32'h0000_0004, 1'b0);

        // D3: high level sets again after a clear
        wr(8'h14, 32'h0000_0008, 4'b1111, 1'b0);
        set_pins(32'h8000_0009);
        waitn(3);
        rd(8'h20, 32'h0000_000C, 1'b0);
        wr(8'h20, 32'h0000_0008, 4'b1111, 1'b0);
        rd(8'h20, 32'h0000_000C, 1'b0);
        set_pins(32'h8000_0001);
        waitn(3);
        wr(8'h20, 32'h0000_0008, 4'b1111, 1'b0);
        rd(8'h20, 32'h0000_0004, 1'b0);

        // D4: low level; clear some pending bits only
        wr(8'h18, 32'h0000_0010, 4'b1111, 1'b0);
        waitn(2);
        rd(8'h20, 32'h0000_0014, 1'b0);
        wr(8'h20, 32'h0000_0004, 4'b1111, 1'b0);
        rd(8'h20, 32'h0000_0010, 1'b0);
        wr(8'h20, 32'h0000_0010, 4'b1111, 1'b0);
        rd(8'h20, 32'h0000_0010, 1'b0);
        wr(8'h18, 32'h0000_0000, 4'b1111, 1'b0);
        wr(8'h20, 32'h0000_0010, 4'b1111, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        // D5: detection beats a clear on the same edge
        set_pins(32'h8000_0003);
        waitn(3);
        rd(8'h20, 32'h0000_0002, 1'b0);
        set_pins(32'h8000_0001);
        waitn(3);
        rd(8'h20, 32'h0000_0002, 1'b0);
        wr_pins(8'h20, 32'h0000_0002, 4'b1111, 32'h8000_0003);
        rd(8'h20, 32'h0000_0002, 1'b0);
        wr(8'h20, 32'h0000_0002, 4'b1111, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        // D6: one-cycle pulse, both edges enabled
        wr(8'h0C, 32'h8000_0023, 4'b1111, 1'b0);
        wr(8'h10, 32'h0000_0024, 4'b1111, 1'b0);
        set_pins(32'h8000_0023);
        set_pins(32'h8000_0003);
        waitn(3);
        rd(8'h20, 32'h0000_0020, 1'b0);
        wr(8'h20, 32'h0000_0020, 4'b1111, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        // Interrupt mask
        wr(8'h0C, 32'h8000_0063, 4'b1111, 1'b0);
        set_pins(32'h8000_0043);
        waitn(3);
        rd(8'h20, 32'h0000_0040, 1'b0);
        chk_irq(1'b0, 1'b0);
        wr(8'h1C, 32'h0000_0040, 4'b1111, 1'b0);
        chk_irq(1'b1, 1'b1);
        wr(8'h1C, 32'h0000_0000, 4'b1110, 1'b0);
        chk_irq(1'b1, 1'b1);
        wr(8'h1C, 32'h0000_0000, 4'b1111, 1'b0);
        chk_irq(1'b0, 1'b0);
        rd(8'h20, 32'h0000_0040, 1'b0);
        wr(8'h1C, 32'h0000_0040, 4'b1111, 1'b0);
        chk_irq(1'b1, 1'b1);
        wr(8'h20, 32'h0000_0040, 4'b1111, 1'b0);
        chk_irq(1'b0, 1'b0);
        rd(8'h20, 32'd0, 1'b0);
        set_pins(32'h0000_0043);
        waitn(3);
        set_pins(32'h8000_0043);
        waitn(3);
        rd(8'h20, 32'h8000_0000, 1'b0);
        wr(8'h1C, 32'h8000_0000, 4'b1111, 1'b0);
        chk_irq(1'b1, 1'b0);
        wr(8'h20, 32'h8000_0000, 4'b1111, 1'b0);
        chk_irq(1'b0, 1'b0);
        wr(8'h1C, 32'h0000_0000, 4'b1111, 1'b0);

        // Back-to-back transfers
        xfer(1'b1, 8'h00, 32'h1111_2222, 4'b1111, 1'b0, 32'd0, 1'b0);
        xfer(1'b0, 8'h00, 32'd0, 4'b0000, 1'b1, 32'h1111_2222, 1'b0);
        xfer(1'b1, 8'h24, 32'd0, 4'b1111, 1'b0, 32'd0, 1'b1);
        xfer(1'b0, 8'h04, 32'd0, 4'b0000, 1'b1, 32'hFF0F_F0C3, 1'b0);
        xfer(1'b1, 8'h04, 32'h0000_5A5A, 4'b0011, 1'b0, 32'd0, 1'b0);
        xfer(1'b0, 8'h04, 32'd0, 4'b0000, 1'b1, 32'hFF0F_5A5A, 1'b0);
        idle;
        chk_pins(32'h1111_2222, 32'hFF0F_5A5A);

        // Reset again, from a busy state
        wr(8'h14, 32'h0000_00FF, 4'b1111, 1'b0);
        wr(8'h1C, 32'h0000_00FF, 4'b1111, 1'b0);
        chk_irq(1'b1, 1'b1);
        do_reset;
        chk_pins(32'd0, 32'd0);
        chk_irq(1'b0, 1'b0);
        rd(8'h00, 32'd0, 1'b0);
        rd(8'h04, 32'd0, 1'b0);
        rd(8'h08, 32'h8000_0043, 1'b0);
        rd(8'h0C, 32'd0, 1'b0);
        rd(8'h10, 32'd0, 1'b0);
        rd(8'h14, 32'd0, 1'b0);
        rd(8'h18, 32'd0, 1'b0);
        rd(8'h1C, 32'd0, 1'b0);
        rd(8'h20, 32'd0, 1'b0);

        waitn(2);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed + mon_pass, failed + mon_fail);
        $finish;
    end

    initial begin : watchdog
        reg [8*64-1:0] wd_nonce;
        integer wd_ok;
        #2000000;
        wd_nonce = 0;
        wd_ok = $value$plusargs("nirmaan_nonce=%s", wd_nonce);
        $error("timeout: testbench did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", wd_nonce, passed + mon_pass, failed + mon_fail + 1);
        $finish;
    end
endmodule
